from pydantic import BaseModel, Field, ValidationError

class SKU(BaseModel):
    code: str = Field(..., regex=r'^[A-Z]{3}-\d{4}$')

def make_sku(code: str):
    try:
        return SKU(code=code)
    except ValidationError as e:
        raise ValueError("Invalid code format") from e
