class RangeModel(BaseModel):
    lo: int
    hi: int

    @model_validator(mode='after')
    def check_range(self) -> 'RangeModel':
        if self.hi < self.lo:
            raise ValidationError('hi must be greater than or equal to lo', model=RangeModel)
        return self

def make_range(lo, hi):
    return RangeModel(lo=lo, hi=hi)
```

