from pydantic import BaseModel, ValidationError, root_validator, conint

class RangeModel(BaseModel):
    lo: conint(ge=0)
    hi: conint(ge=0)

    @root_validator(pre=True)
    def check_lo_le_hi(cls, values):
        lo = values.get('lo')
        hi = values.get('hi')
        if lo is not None and hi is not None and hi < lo:
            raise ValueError('hi must be greater than or equal to lo')
        return values

def make_range(lo, hi):
    return RangeModel(lo=lo, hi=hi)
```

