def to_record(model):
    """
    Takes an instance of any pydantic model and returns its field values as a plain Python dict keyed by field name,
    using the model's own serialisation method.

    Supports both pydantic v1 and v2 models.
    """
    # Check if it's a pydantic v2 model (has model_dump method)
    if hasattr(model, 'model_dump'):
        return model.model_dump()
    # Fallback to pydantic v1 (has dict method)
    elif hasattr(model, 'dict'):
        return model.dict()
    else:
        raise TypeError("Provided object is not a pydantic model")
