from pydantic import BaseModel, root_validator, ValidationError


class RangeModel(BaseModel):
    lo: int
    hi: int

    @root_validator
    def validate_range(cls, values):
        lo = values.get('lo')
        hi = values.get('hi')
        if hi < lo:
            raise ValidationError('hi must be greater than or equal to lo', cls)
        return values


def make_range(lo, hi):
    return RangeModel(lo=lo, hi=hi)
```

