from pydantic import BaseModel, validator

class User(BaseModel):
    name: str

    @validator('name')
    def name_must_not_be_empty(cls, v):
        if not v or v.isspace():
            raise ValueError('Name must not be empty or whitespace-only')
        return v

def make_user(name):
    return User(name=name)
```

